function draw() {
  ctx.clearRect(0, 0, W, H);

  // Ship
  ctx.fillStyle = '#0cf';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h);
  ctx.lineTo(ship.x + ship.w / 2, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();

  // Hook
  if (hook.active) {
    ctx.fillStyle = '#fff';
    ctx.fillRect(hook.x, hook.y - hook.length, hookWidth, hook.length);
  }

  // Debris
  debris.forEach(d => {
    ctx.fillStyle = d.danger ? '#f44' : '#aaa';
    ctx.fillRect(d.x, d.y, d.w, d.h);
  });

  // UI
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`Time: ${timeLeft}`, W - 100, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = '32px sans-serif';
    ctx.fillText('Game Over', W / 2, H / 2 - 20);
    ctx.font = '24px sans-serif';
    ctx.fillText(`Final Score: ${score}`, W / 2, H / 2 + 20);
  }
}

input.newString:
function draw() {
  // Background: dark space with starfield
  ctx.fillStyle = '#001020';
  ctx.fillRect(0, 0, W, H);
  drawStars();

  // Ship (triangle with slight gradient)
  const shipGrad = ctx.createLinearGradient(ship.x, ship.y, ship.x, ship.y + ship.h);
  shipGrad.addColorStop(0, '#00aaff');
  shipGrad.addColorStop(1, '#004466');
  ctx.fillStyle = shipGrad;
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h);
  ctx.lineTo(ship.x + ship.w / 2, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();

  // Hook (white line with circular tip)
  if (hook.active) {
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = hookWidth;
    ctx.beginPath();
    ctx.moveTo(hook.x + hookWidth / 2, hook.y);
    ctx.lineTo(hook.x + hookWidth / 2, hook.y - hook.length);
    ctx.stroke();
    // tip circle
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(hook.x + hookWidth / 2, hook.y - hook.length, hookWidth * 1.5, 0, Math.PI * 2);
    ctx.fill();
  }

  // Debris: junk as gray rectangles, asteroids as red polygons
  debris.forEach(d => {
    if (d.danger) {
      // draw asteroid as rough polygon
      ctx.fillStyle = '#b33';
      ctx.beginPath();
      const cx = d.x + d.w / 2;
      const cy = d.y + d.h / 2;
      const points = 7;
      for (let i = 0; i < points; i++) {
        const angle = (i / points) * Math.PI * 2;
        const radius = d.w / 2 * (0.7 + Math.random() * 0.6);
        ctx.lineTo(cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius);
      }
      ctx.closePath();
      ctx.fill();
    } else {
      ctx.fillStyle = '#888';
      ctx.fillRect(d.x, d.y, d.w, d.h);
    }
  });

  // UI overlay
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`Time: ${timeLeft}`, W - 100, 20);

  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = '32px sans-serif';
    ctx.fillText('Game Over', W / 2, H / 2 - 20);
    ctx.font = '24px sans-serif';
    ctx.fillText(`Final Score: ${score}`, W / 2, H / 2 + 20);
  }
}

// Starfield helper (simple static stars)
const stars = [];
function initStars(count = 100) {
  for (let i = 0; i < count; i++) {
    stars.push({
      x: Math.random() * W,
      y: Math.random() * H,
      radius: Math.random() * 1.5 + 0.5,
    });
  }
}
function drawStars() {
  ctx.fillStyle = '#fff';
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fill();
  });
}

// Initialize stars once
initStars();

